    // Write implements io.Writer.
    std::tuple<int, gocpp::error> rec::Write(FD* fd, gocpp::slice<unsigned char> buf)
    {
        gocpp::Defer defer;
        try
        {
            if(fd->kind == kindFile)
            {
                if(auto err = rec::readWriteLock(gocpp::recv(fd)); err != nullptr)
                {
                    return {0, err};
                }
                defer.push_back([=]{ rec::readWriteUnlock(gocpp::recv(fd)); });
            }
            else
            {
                if(auto err = rec::writeLock(gocpp::recv(fd)); err != nullptr)
                {
                    return {0, err};
                }
                defer.push_back([=]{ rec::writeUnlock(gocpp::recv(fd)); });
            }

            int ntotal = {};
            for(; ; )
            {
                auto max = len(buf);
                if(max - ntotal > maxRW)
                {
                    max = ntotal + maxRW;
                }
                auto b = buf.make_slice(ntotal, max);
                int n = {};
                gocpp::error err = {};
                //Go switch emulation
                {
                    auto condition = fd->kind;
                    int conditionId = -1;
                    if(condition == kindConsole) { conditionId = 0; }
                    else if(condition == kindPipe) { conditionId = 1; }
                    else if(condition == kindFile) { conditionId = 2; }
                    else if(condition == kindNet) { conditionId = 3; }
                    switch(conditionId)
                    {
                        case 0:
                            std::tie(n, err) = rec::writeConsole(gocpp::recv(fd), b);
                            break;
                        case 1:
                        case 2:
                            std::tie(n, err) = rec::execIO(gocpp::recv(fd), 'w', [=](operation* o) mutable -> std::tuple<uint32_t, gocpp::error>
                            {
                                uint32_t qty;
                                gocpp::error err;
                                err = syscall::WriteFile(fd->Sysfd, b, & qty, rec::overlapped(gocpp::recv(fd), o));
                                return {qty, err};
                            }, pinPtrsFromBuf(b));
                            rec::addOffset(gocpp::recv(fd), n);
                            break;
                        case 3:
                            if(race::Enabled)
                            {
                                race::ReleaseMerge(gocpp::unsafe_pointer(& ioSync));
                            }
                            std::tie(n, err) = rec::execIO(gocpp::recv(fd), 'w', [=](operation* o) mutable -> std::tuple<uint32_t, gocpp::error>
                            {
                                uint32_t qty;
                                gocpp::error err;
                                err = syscall::WSASend(fd->Sysfd, newWsaBuf(b), 1, & qty, 0, & o->o, nullptr);
                                return {qty, err};
                            }, pinPtrsFromBuf(b));
                            break;
                    }
                }
                ntotal += n;
                if(ntotal == len(buf) || err != nullptr)
                {
                    return {ntotal, err};
                }
                if(n == 0)
                {
                    return {ntotal, io::ErrUnexpectedEOF};
                }
            }
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

    // writeConsole writes len(b) bytes to the console File.
    // It returns the number of bytes written and an error, if any.
    std::tuple<int, gocpp::error> rec::writeConsole(FD* fd, gocpp::slice<unsigned char> b)
    {
        auto n = len(b);
        auto runes = gocpp::make(gocpp::Tag<gocpp::slice<gocpp::rune>>(), 0, 256);
        if(len(fd->lastbits) > 0)
        {
            b = append(fd->lastbits, b);
            fd->lastbits = nullptr;
        }
        for(; len(b) >= utf8::UTFMax || utf8::FullRune(b); )
        {
            auto [r, l] = utf8::DecodeRune(b);
            runes = append(runes, r);
            b = b.make_slice(l);
        }
        if(len(b) > 0)
        {
            fd->lastbits = gocpp::make(gocpp::Tag<gocpp::slice<unsigned char>>(), len(b));
            copy(fd->lastbits, b);
        }
        // syscall.WriteConsole seems to fail, if given large buffer.
        // So limit the buffer to 16000 characters. This number was
        // discovered by experimenting with syscall.WriteConsole.
        auto maxWrite = 16000;
        for(; len(runes) > 0; )
        {
            auto m = len(runes);
            if(m > maxWrite)
            {
                m = maxWrite;
            }
            auto chunk = runes.make_slice(0, m);
            runes = runes.make_slice(m);
            auto uint16s = utf16::Encode(chunk);
            for(; len(uint16s) > 0; )
            {
                uint32_t written = {};
                auto err = syscall::WriteConsole(fd->Sysfd, & uint16s[0], uint32_t(len(uint16s)), & written, nullptr);
                if(err != nullptr)
                {
                    return {0, err};
                }
                uint16s = uint16s.make_slice(written);
            }
        }
        return {n, nullptr};
    }

    // Pwrite emulates the Unix pwrite system call.
    std::tuple<int, gocpp::error> rec::Pwrite(FD* fd, gocpp::slice<unsigned char> buf, int64_t off)
    {
        gocpp::Defer defer;
        try
        {
            if(fd->kind == kindPipe)
            {
                // Pwrite does not work with pipes
                return {0, gocpp::error(syscall::go_ESPIPE)};
            }

            if(auto err = rec::readWriteLock(gocpp::recv(fd)); err != nullptr)
            {
                return {0, err};
            }
            defer.push_back([=]{ rec::readWriteUnlock(gocpp::recv(fd)); });

            int ntotal = {};
            for(; ; )
            {
                auto max = len(buf);
                if(max - ntotal > maxRW)
                {
                    max = ntotal + maxRW;
                }
                auto b = buf.make_slice(ntotal, max);
                auto [n, err_tmp] = rec::execIO(gocpp::recv(fd), 'w', [=](operation* o) mutable -> std::tuple<uint32_t, gocpp::error>
                {
                    uint32_t qty;
                    gocpp::error err;
                    gocpp::Defer defer;
                    try
                    {
                        // Overlapped handles don't have the file pointer updated
                        // when performing I/O operations, so there is no need to
                        // call Seek to reset the file pointer.
                        // Also, some overlapped file handles don't support seeking.
                        // See https://go.dev/issues/74951.
                        if(fd->isBlocking)
                        {
                            auto [curoffset, err] = syscall::Seek(fd->Sysfd, 0, io::SeekCurrent);
                            if(err != nullptr)
                            {
                                return {0, err};
                            }
                            defer.push_back([=]{ syscall::Seek(fd->Sysfd, curoffset, io::SeekStart); });
                        }
                        rec::setOffset(gocpp::recv(o), off + int64_t(ntotal));

                        err = syscall::WriteFile(fd->Sysfd, b, & qty, & o->o);
                        return {qty, err};
                    }
                    catch(gocpp::GoPanic& gp)
                    {
                        defer.handlePanic(gp);
                        return {qty, err};
                    }
                }, pinPtrsFromBuf(b));
                auto& err = err_tmp;
                if(n > 0)
                {
                    ntotal += n;
                }
                if(ntotal == len(buf) || err != nullptr)
                {
                    return {ntotal, err};
                }
                if(n == 0)
                {
                    return {ntotal, io::ErrUnexpectedEOF};
                }
            }
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

    // Writev emulates the Unix writev system call.
    std::tuple<int64_t, gocpp::error> rec::Writev(FD* fd, gocpp::slice<gocpp::slice<unsigned char>>* buf)
    {
        gocpp::Defer defer;
        try
        {
            if(len(*buf) == 0)
            {
                return {0, nullptr};
            }
            if(auto err = rec::writeLock(gocpp::recv(fd)); err != nullptr)
            {
                return {0, err};
            }
            defer.push_back([=]{ rec::writeUnlock(gocpp::recv(fd)); });
            if(race::Enabled)
            {
                race::ReleaseMerge(gocpp::unsafe_pointer(& ioSync));
            }
            auto bufs = newWSABufs(buf);
            defer.push_back([=]{ freeWSABufs(bufs); });
            auto [n, err_tmp] = rec::execIO(gocpp::recv(fd), 'w', [=](operation* o) mutable -> std::tuple<uint32_t, gocpp::error>
            {
                uint32_t qty;
                gocpp::error err;
                err = syscall::WSASend(fd->Sysfd, & (*bufs)[0], uint32_t(len(*bufs)), & qty, 0, & o->o, nullptr);
                return {qty, err};
            });
            auto& err = err_tmp;
            TestHookDidWritev(n);
            consume(buf, int64_t(n));
            return {int64_t(n), err};
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

    // WriteTo wraps the sendto network call.
    std::tuple<int, gocpp::error> rec::WriteTo(FD* fd, gocpp::slice<unsigned char> buf, syscall::Sockaddr sa)
    {
        gocpp::Defer defer;
        try
        {
            if(auto err = rec::writeLock(gocpp::recv(fd)); err != nullptr)
            {
                return {0, err};
            }
            defer.push_back([=]{ rec::writeUnlock(gocpp::recv(fd)); });

            if(len(buf) == 0)
            {
                // handle zero-byte payload
                auto [n, err_tmp] = rec::execIO(gocpp::recv(fd), 'w', [=](operation* o) mutable -> std::tuple<uint32_t, gocpp::error>
                {
                    uint32_t qty;
                    gocpp::error err;
                    err = syscall::WSASendto(fd->Sysfd, new syscall::WSABuf {}, 1, & qty, 0, sa, & o->o, nullptr);
                    return {qty, err};
                });
                auto& err = err_tmp;
                return {n, err};
            }

            auto ntotal = 0;
            for(; len(buf) > 0; )
            {
                auto b = buf;
                if(len(b) > maxRW)
                {
                    b = b.make_slice(0, maxRW);
                }
                auto [n, err_tmp] = rec::execIO(gocpp::recv(fd), 'w', [=](operation* o) mutable -> std::tuple<uint32_t, gocpp::error>
                {
                    uint32_t qty;
                    gocpp::error err;
                    err = syscall::WSASendto(fd->Sysfd, newWsaBuf(b), 1, & qty, 0, sa, & o->o, nullptr);
                    return {qty, err};
                }, unsafe::SliceData(b));
                auto& err = err_tmp;
                ntotal += int(n);
                if(err != nullptr)
                {
                    return {ntotal, err};
                }
                buf = buf.make_slice(n);
            }
            return {ntotal, nullptr};
        }
        catch(gocpp::GoPanic& gp)
        {
            defer.handlePanic(gp);
        }
    }

